// Obiekty w mieście i okolicy (scope 'city'): przyroda, dziedzictwo przemysłowe, historia i kultura.
const city = [
  // ——— Przyroda: Kompleks Pogoria ———
  { id: 'pogoria-1', name: L('Pogoria I', 'Pogoria I lake'), kind: 'nature', scope: 'city', lat: 50.3390, lng: 19.2020, site: null, building: null, districtId: 'reden',
    short: L('Najstarsze z jezior Pogorii – powstało w 1943 r. w wyrobisku piasku podsadzkowego.', 'The oldest of the Pogoria lakes – formed in 1943 in a pit where backfill sand was dug.'),
    description: L('Jezioro o powierzchni ok. 73 ha zajmuje dawne wyrobisko piasku, który wykorzystywano w kopalniach do podsadzania wyrobisk. Przed laty było najpopularniejszym kąpieliskiem w mieście, dziś przyciąga spokojem.\n\nNa jego brzegach zachowały się fragmenty torfowiskowej roślinności chronionej jako użytek ekologiczny „Młaki nad Pogorią I”.', 'The 73-hectare lake fills an old pit where sand was dug to backfill mine workings. Years ago it was the city’s most popular bathing spot; today it draws people looking for calm.\n\nPatches of fen vegetation on its shores are protected as the “Młaki nad Pogorią I” ecological site.'),
    accessible: true, accessNote: L('Asfaltowa ścieżka wzdłuż części brzegu, parking z miejscami dla osób z niepełnosprawnościami.', 'Asphalt path along part of the shore, car park with accessible bays.'), protection: L('Część brzegów – użytek ekologiczny', 'Part of the shore – ecological site'), tags: ['woda', 'pogoria', 'kapielisko'], ill: 'lake' },
  { id: 'pogoria-2', name: L('Pogoria II', 'Pogoria II lake'), kind: 'nature', scope: 'city', lat: 50.3445, lng: 19.2140, site: null, building: null, districtId: 'pieklo',
    short: L('Małe, płytkie jezioro w szerokim pasie szuwarów – najbogatsze w ptaki z całej Pogorii.', 'A small, shallow lake in a wide reed belt – the richest in birds of all the Pogoria lakes.'),
    description: L('Od 2002 r. jezioro wraz z brzegami (ok. 40 ha) jest użytkiem ekologicznym. Kąpiel i sporty wodne są tu zabronione, dzięki czemu gniazdują bączek, remiz i zimorodek, a w szuwarach słychać kilka gatunków trzciniaków.\n\nTo najlepsze miejsce w mieście na spokojną obserwację ptaków z lornetką.', 'Since 2002 the lake and its shores (about 40 ha) have been an ecological site. Swimming and water sports are banned, so little bitterns, penduline tits and kingfishers nest here, and several warbler species sing in the reeds.\n\nIt is the best place in the city for quiet birdwatching.'),
    accessible: false, accessNote: L('Ścieżki gruntowe, miejscami podmokłe.', 'Dirt paths, wet in places.'), protection: L('Użytek ekologiczny „Pogoria II” (2002)', '“Pogoria II” ecological site (2002)'), tags: ['ptaki', 'pogoria', 'uzytek'], ill: 'wetland' },
  { id: 'pogoria-3', name: L('Pogoria III', 'Pogoria III lake'), kind: 'nature', scope: 'city', lat: 50.3500, lng: 19.2250, site: null, building: null, districtId: 'pieklo',
    short: L('Najchętniej odwiedzane jezioro: piaszczyste plaże, molo, żeglarstwo i ścieżka dookoła.', 'The most visited lake: sandy beaches, a pier, sailing and a loop path.'),
    description: L('Pogoria III ma ok. 200 ha powierzchni i wokół niej biegnie popularna pętla spacerowo-rowerowa. Latem działają tu strzeżone kąpieliska i przystanie, a na głębszych wodach pływają żaglówki i kajaki.\n\nJak pozostałe jeziora Pogorii, powstała w wyrobisku piasku zasilanym wodami zlewni Czarnej Przemszy.', 'Pogoria III covers about 200 ha and a popular walking and cycling loop runs around it. In summer there are lifeguarded beaches and marinas, and sailing boats and kayaks use the deeper water.\n\nLike the other Pogoria lakes, it fills a former sand pit fed by the Czarna Przemsza catchment.'),
    accessible: true, accessNote: L('Utwardzona pętla wokół jeziora, dostępne molo i toalety przy plaży.', 'Paved loop around the lake, accessible pier and beach toilets.'), protection: null, tags: ['woda', 'pogoria', 'plaza', 'rower'], ill: 'lake' },
  { id: 'pogoria-4', name: L('Pogoria IV (Kuźnica Warężyńska)', 'Pogoria IV (Kuźnica Warężyńska reservoir)'), kind: 'nature', scope: 'city', lat: 50.3700, lng: 19.2200, site: null, building: null, districtId: 'pieklo',
    short: L('Największy i najmłodszy zbiornik (2005 r., ok. 560 ha) – przeciwpowodziowy, rekreacyjny i ptasi.', 'The largest and youngest reservoir (2005, about 560 ha) – for flood control, recreation and birds.'),
    description: L('Zbiornik utworzono w 2005 r. w wyrobisku piasku eksploatowanym przez ponad 30 lat. Ma ok. 23 m głębokości i ok. 13 km linii brzegowej; zasilają go Czarna Przemsza i Trzebyczka. Jego główną funkcją jest ochrona przeciwpowodziowa.\n\nOdnotowano tu ponad 200 gatunków ptaków, a na wschodnim brzegu leży obszar Natura 2000 „Lipienniki w Dąbrowie Górniczej”.', 'The reservoir was created in 2005 in a sand pit worked for more than 30 years. It is about 23 m deep with some 13 km of shoreline, fed by the Czarna Przemsza and the Trzebyczka. Its main role is flood protection.\n\nOver 200 bird species have been recorded here, and the Natura 2000 site “Lipienniki w Dąbrowie Górniczej” lies on the eastern shore.'),
    accessible: true, accessNote: L('Ścieżka rowerowa po koronie zapory; plaże piaszczyste – ograniczona dostępność.', 'Cycle path along the dam crest; sandy beaches have limited access.'), protection: L('Natura 2000 „Lipienniki w Dąbrowie Górniczej” (wschodni brzeg)', 'Natura 2000 “Lipienniki w Dąbrowie Górniczej” (east shore)'), tags: ['woda', 'pogoria', 'ptaki', 'natura2000'], ill: 'lake' },
  { id: 'mlaki-nad-pogoria', name: L('Młaki nad Pogorią I', 'Młaki nad Pogorią I fens'), kind: 'nature', scope: 'city', lat: 50.3370, lng: 19.1985, site: null, building: null, districtId: 'reden',
    short: L('Użytek ekologiczny z rzadkimi młakami, storczykami i rosiczkami.', 'An ecological site with rare fens, orchids and sundews.'),
    description: L('Ok. 7 ha podmokłych młak między Pogorią I a linią kolejową chroni się od lat 90. XX w. Rosną tu storczyki i rosiczki, choć część populacji wyraźnie się zmniejszyła.\n\nTo przykład przyrody, która odrodziła się w sąsiedztwie dawnego wyrobiska – i wymaga dziś ochrony przed przesuszeniem.', 'About 7 ha of wet fens between Pogoria I and the railway line have been protected since the 1990s. Orchids and sundews grow here, although some populations have declined sharply.\n\nIt shows nature reviving next to an old pit – and now needing protection from drying out.'),
    accessible: false, accessNote: L('Teren podmokły, oglądanie tylko z obrzeży.', 'Wet ground, view from the edge only.'), protection: L('Użytek ekologiczny', 'Ecological site'), tags: ['torfowisko', 'storczyki', 'uzytek'], ill: 'wetland' },
  { id: 'bielowizna', name: L('Bielowizna', 'Bielowizna'), kind: 'nature', scope: 'city', lat: 50.3740, lng: 19.2600, site: null, building: null, districtId: 'zabkowice',
    short: L('Łęg w dolinie Trzebyczki z ok. 20 gatunkami roślin chronionych lub rzadkich.', 'A floodplain forest in the Trzebyczka valley with about 20 protected or rare plant species.'),
    description: L('Kilkusetmetrowy odcinek doliny Trzebyczki przy ul. Kusocińskiego porasta wilgotny las łęgowy. Należy do kompleksu przyrodniczego Pogorii.\n\nWiosną dno lasu pokrywają kwitnące geofity.', 'A few hundred metres of the Trzebyczka valley near ul. Kusocińskiego are covered by wet floodplain forest, part of the Pogoria nature complex.\n\nIn spring the forest floor is carpeted with flowering bulbs and tubers.'),
    accessible: false, accessNote: L('Wąskie ścieżki leśne.', 'Narrow forest paths.'), protection: null, tags: ['las', 'dolina', 'pogoria'], ill: 'forest' },
  { id: 'basiula', name: L('Basiula', 'Basiula pond'), kind: 'nature', scope: 'city', lat: 50.3640, lng: 19.2570, site: null, building: null, districtId: 'zabkowice',
    short: L('Niewielki staw z czystą wodą – ważne miejsce rozrodu płazów.', 'A small clear-water pond – an important amphibian breeding site.'),
    description: L('Sztuczny staw o powierzchni ok. 1 ha w Ząbkowicach, w pobliżu węzła drogi S1. Wiosną odbywają tu gody żaby i traszki.\n\nNa trasie przyrodniczej uczymy się, dlaczego płazy potrzebują bezpiecznych przejść przez drogi.', 'An artificial pond of about 1 ha in Ząbkowice, near the S1 junction. In spring frogs and newts breed here.\n\nOn the nature trail you learn why amphibians need safe road crossings.'),
    accessible: false, accessNote: L('Brak utwardzonego dojścia.', 'No paved access.'), protection: null, tags: ['plazy', 'staw', 'pogoria'], ill: 'wetland' },
  { id: 'bagna-nad-trzebyczka', name: L('Bagna nad Trzebyczką', 'Trzebyczka marshes'), kind: 'nature', scope: 'city', lat: 50.3570, lng: 19.2450, site: null, building: null, districtId: 'antoniow',
    short: L('Dawna dolina z olsami, turzycowiskami i oczkami wodnymi.', 'An old valley with alder carr, sedge beds and small pools.'),
    description: L('Między ul. Konstytucji a drogą S1 rozciąga się podmokłe obniżenie z olsami i oczkami wodnymi. To część kompleksu Pogoria i korytarz ekologiczny dla płazów i ptaków.\n\nMiejsce najlepiej oglądać wiosną, gdy woda stoi najwyżej.', 'Between ul. Konstytucji and the S1 lies a wet hollow with alder carr and pools – part of the Pogoria complex and an ecological corridor for amphibians and birds.\n\nIt is best seen in spring, when the water is highest.'),
    accessible: false, accessNote: L('Teren podmokły.', 'Wet ground.'), protection: null, tags: ['bagna', 'ols', 'pogoria'], ill: 'wetland' },
  { id: 'bagna-w-antoniowie', name: L('Bagna w Antoniowie', 'Antoniów marshes'), kind: 'nature', scope: 'city', lat: 50.3620, lng: 19.2380, site: null, building: null, districtId: 'antoniow',
    short: L('Użytek ekologiczny z rzadkim torfowiskiem przejściowym i lipiennikiem Loesela.', 'An ecological site with a rare transitional mire and Loesel’s twayblade orchid.'),
    description: L('Niewielki (ok. 3 ha) fragment dawnego koryta Trzebyczki chroni się od 2001 r. Na torfowisku przejściowym stwierdzono ok. 350 gatunków roślin naczyniowych, w tym lipiennika Loesela – storczyka chronionego w całej Unii Europejskiej.\n\nObszar należy do sieci Natura 2000 „Lipienniki w Dąbrowie Górniczej”.', 'A small (about 3 ha) section of the old Trzebyczka channel has been protected since 2001. Some 350 vascular plant species grow on the transitional mire, including Loesel’s twayblade – an orchid protected across the EU.\n\nThe area is part of the Natura 2000 site “Lipienniki w Dąbrowie Górniczej”.'),
    accessible: false, accessNote: L('Wstęp tylko po ścieżce brzegowej; teren grząski.', 'Access only along the edge path; boggy ground.'), protection: L('Użytek ekologiczny (2001), Natura 2000', 'Ecological site (2001), Natura 2000'), tags: ['torfowisko', 'storczyki', 'natura2000'], ill: 'wetland' },
  // ——— Przyroda: obszary chronione ———
  { id: 'wzgorze-golonoskie', name: L('Wzgórze Gołonoskie', 'Gołonóg Hill'), kind: 'nature', scope: 'city', lat: 50.3460, lng: 19.2410, site: null, building: null, districtId: 'golonog',
    short: L('Zespół przyrodniczo-krajobrazowy: stare drzewa wokół kościoła i cmentarza oraz punkt widokowy.', 'A nature and landscape complex: old trees around a church and cemetery, and a viewpoint.'),
    description: L('Wzniesienie w Gołonogu z zabytkowym kościołem i cmentarzem otacza starodrzew. Ok. 6,5 ha chroni się jako zespół przyrodniczo-krajobrazowy.\n\nZe szczytu rozciąga się widok na miasto, jeziora Pogoria i dymiące na horyzoncie kominy kombinatu.', 'A hill in Gołonóg with a historic church and cemetery is ringed by old trees. About 6.5 ha are protected as a nature and landscape complex.\n\nFrom the top you can see the city, the Pogoria lakes and the steel plant chimneys on the horizon.'),
    accessible: false, accessNote: L('Strome podejście; dojazd samochodem pod kościół.', 'Steep climb; car access up to the church.'), protection: L('Zespół przyrodniczo-krajobrazowy', 'Nature and landscape complex'), tags: ['wzgorze', 'widok', 'starodrzew'], ill: 'church' },
  { id: 'wywierzyska', name: L('Wywierzyska w Strzemieszycach Wielkich', 'Strzemieszyce Wielkie karst springs'), kind: 'nature', scope: 'city', lat: 50.3100, lng: 19.2900, site: null, building: null, districtId: 'strzemieszyce-wielkie',
    short: L('Pomnik przyrody: wydajne źródła krasowe (ok. 50 l/s) z fauną źródliskową.', 'A natural monument: productive karst springs (about 50 l/s) with spring fauna.'),
    description: L('Przy ul. Strzemieszyckiej z wapiennego podłoża wypływa woda o wydajności ok. 50 litrów na sekundę. Chłodne, czyste źródła są tarliskiem pstrąga i domem rzadkich bezkręgowców.\n\nObszar ok. 1,3 ha jest pomnikiem przyrody od 1996 r.', 'On ul. Strzemieszycka water wells up from limestone at about 50 litres per second. The cool, clean springs are a trout spawning ground and home to rare invertebrates.\n\nThe 1.3-hectare area has been a natural monument since 1996.'),
    accessible: true, accessNote: L('Dojście chodnikiem od ulicy, punkt obserwacyjny z poziomu terenu.', 'Pavement access from the street, viewpoint at ground level.'), protection: L('Pomnik przyrody (1996)', 'Natural monument (1996)'), tags: ['zrodla', 'kras', 'woda'], ill: 'river' },
  { id: 'srocza-gora', name: L('Srocza Góra', 'Srocza Góra'), kind: 'nature', scope: 'city', lat: 50.3050, lng: 19.2980, site: null, building: null, districtId: 'strzemieszyce-wielkie',
    short: L('Stanowisko dokumentacyjne – odsłonięcie wapieni triasowych w dawnym kamieniołomie.', 'A geological documentation site – Triassic limestone exposed in an old quarry.'),
    description: L('Przy drodze nr 94 odsłania się ok. 300-metrowy profil skał sprzed ponad 200 milionów lat, gdy tereny Zagłębia pokrywało ciepłe morze. Ślady dawnego kamieniołomu są też świadectwem lokalnego wydobycia wapienia.\n\nMiejsce służy jako plenerowa sala do zajęć z geologii.', 'Beside road 94 a 300-metre profile of rocks over 200 million years old is exposed, from a time when a warm sea covered the region. Remains of an old quarry also show local limestone extraction.\n\nThe site serves as an outdoor geology classroom.'),
    accessible: false, accessNote: L('Nierówny teren, skarpy.', 'Uneven ground, slopes.'), protection: L('Stanowisko dokumentacyjne (2007)', 'Geological documentation site (2007)'), tags: ['geologia', 'wapien', 'kamieniolom'], ill: 'quarry' },
  { id: 'pustynia-bledowska', name: L('Pustynia Błędowska', 'Błędów Desert'), kind: 'nature', scope: 'city', lat: 50.3530, lng: 19.4560, site: null, building: null, districtId: 'bledow',
    short: L('Największy w Polsce obszar śródlądowych lotnych piasków, częściowo w granicach miasta.', 'Poland’s largest area of inland drifting sand, partly within the city limits.'),
    description: L('Pustynia rozciąga się od Błędowa po Klucze. Jej powstanie przyspieszyło wycinanie lasów na potrzeby górnictwa i hutnictwa. Dziś jest chroniona w sieci Natura 2000, a w granicach Dąbrowy – jako użytek ekologiczny.\n\nPiaski stopniowo zarastają, dlatego prowadzi się tu prace przywracające otwarty krajobraz wydm. Punkty widokowe znajdują się m.in. po małopolskiej stronie.', 'The desert stretches from Błędów to Klucze. Its formation was accelerated by forest clearance for mining and metallurgy. Today it is protected under Natura 2000 and, within Dąbrowa, as an ecological site.\n\nThe sands are gradually becoming overgrown, so work is under way to restore the open dune landscape. Viewpoints include those on the Lesser Poland side.'),
    accessible: false, accessNote: L('Sypki piasek; dostępne punkty widokowe przy parkingach po stronie małopolskiej.', 'Loose sand; accessible viewpoints at car parks on the Lesser Poland side.'), protection: L('Natura 2000; użytek ekologiczny (część w Dąbrowie Górniczej)', 'Natura 2000; ecological site (Dąbrowa part)'), tags: ['pustynia', 'wydmy', 'natura2000'], ill: 'desert' },
  { id: 'kozi-rog', name: L('Kozi Róg', 'Kozi Róg'), kind: 'nature', scope: 'city', lat: 50.3500, lng: 19.4400, site: null, building: null, districtId: 'bledow',
    short: L('Fragment Pustyni Błędowskiej z resztkami wydm i starymi sosnami.', 'A part of the Błędów Desert with remnant dunes and old pines.'),
    description: L('Okolice ujścia Centurii do Białej Przemszy kryją pozostałości wydm i powykręcane wiatrem sosny. To dobre miejsce, by zobaczyć, jak las wkracza na piaski.\n\nW aplikacji porównasz widok współczesny z archiwalną mapą sprzed zarastania pustyni.', 'Around the mouth of the Centuria into the Biała Przemsza lie remnant dunes and wind-twisted pines – a good place to see forest creeping onto the sand.\n\nIn the app you can compare today’s view with an archive map from before the desert was overgrown.'),
    accessible: false, accessNote: L('Piaszczyste ścieżki.', 'Sandy paths.'), protection: L('W granicach użytku ekologicznego Pustynia Błędowska', 'Within the Błędów Desert ecological site'), tags: ['wydmy', 'sosny', 'pustynia'], ill: 'desert' },
  { id: 'bagna-bledowskie', name: L('Bagna Błędowskie', 'Błędów marshes'), kind: 'nature', scope: 'city', lat: 50.3450, lng: 19.4350, site: null, building: null, districtId: 'bledow',
    short: L('Odradzająca się dolina Białej Przemszy – bobry, łosie i rzadkie ryby.', 'The recovering Biała Przemsza valley – beavers, elks and rare fish.'),
    description: L('Dolina Białej Przemszy w Błędowie wraca do stanu naturalnego. Bobry budują tamy, pojawiają się łosie, a w rzece żyją minogi.\n\nObszar leży w otulinie Parku Krajobrazowego Orlich Gniazd.', 'The Biała Przemsza valley at Błędów is returning to a natural state. Beavers build dams, elks appear and lampreys live in the river.\n\nThe area lies in the buffer zone of the Eagles’ Nests Landscape Park.'),
    accessible: false, accessNote: L('Teren podmokły, brak kładek.', 'Wet ground, no boardwalks.'), protection: L('Otulina Parku Krajobrazowego Orlich Gniazd', 'Buffer zone of the Eagles’ Nests Landscape Park'), tags: ['dolina', 'bobry', 'rzeka'], ill: 'river' },
  { id: 'bagna-laski-krzykawka', name: L('Bagna Laski – Krzykawka', 'Laski–Krzykawka marshes'), kind: 'nature', scope: 'city', lat: 50.3400, lng: 19.4650, site: null, building: null, districtId: 'bledow',
    short: L('Podmokłe tereny na wschodnim krańcu miasta, w sąsiedztwie Pustyni Błędowskiej.', 'Wetlands on the eastern edge of the city, next to the Błędów Desert.'),
    description: L('Mokradła na pograniczu Dąbrowy Górniczej i sąsiednich gmin tworzą mozaikę turzycowisk i zarośli. Kontrastują z suchymi piaskami pustyni położonej tuż obok.\n\n(Opis ogólny – szczegóły do uzupełnienia w CMS na podstawie inwentaryzacji przyrodniczej.)', 'Wetlands on the border of Dąbrowa Górnicza and neighbouring municipalities form a mosaic of sedge beds and scrub, in stark contrast to the dry sands of the desert next door.\n\n(General description – details to be added in the CMS from the nature survey.)'),
    accessible: false, accessNote: L('Brak udogodnień.', 'No facilities.'), protection: null, tags: ['bagna', 'mokradla'], ill: 'wetland' },
  { id: 'laki-kosaccowe', name: L('Łąki Kosaćcowe Trzebyczka – Tucznawa', 'Trzebyczka–Tucznawa iris meadows'), kind: 'nature', scope: 'city', lat: 50.3880, lng: 19.2800, site: null, building: null, districtId: 'tucznawa',
    short: L('Pas łąk trzęślicowych z kosaćcem syberyjskim i pełnikiem europejskim.', 'A strip of purple moor-grass meadows with Siberian iris and globeflower.'),
    description: L('Wzdłuż torów w Tucznawie ciągnie się ok. 1,2 km wilgotnych łąk. Na przełomie maja i czerwca kwitną tu niebieskie kosaćce syberyjskie i żółte pełniki.\n\nŁąki przetrwają tylko przy późnym, jednorazowym koszeniu – bez niego zarosną krzewami.', 'About 1.2 km of wet meadows run along the railway in Tucznawa. In late May and June blue Siberian irises and yellow globeflowers bloom here.\n\nThe meadows survive only with a single late mowing – without it they turn to scrub.'),
    accessible: false, accessNote: L('Ścieżka gruntowa wzdłuż łąk.', 'Dirt path along the meadows.'), protection: L('Otulina Parku Krajobrazowego Orlich Gniazd', 'Buffer zone of the Eagles’ Nests Landscape Park'), tags: ['laka', 'kosaciec', 'kwiaty'], ill: 'wetland' },
  { id: 'mokrznia', name: L('Mokrznia', 'Mokrznia'), kind: 'nature', scope: 'city', lat: 50.4000, lng: 19.3300, site: null, building: null, districtId: 'leka',
    short: L('Lasy i łąki na granicy z Łazami – 18 gatunków roślin chronionych, także górskich.', 'Woods and meadows on the Łazy border – 18 protected plant species, including mountain ones.'),
    description: L('Na pograniczu Dąbrowy Górniczej i Łaz mozaika lasów i łąk kryje 18 chronionych gatunków roślin. Niektóre z nich to rośliny typowe dla gór – rzadkość na wyżynie.\n\nObszar leży w otulinie Parku Krajobrazowego Orlich Gniazd.', 'On the Dąbrowa–Łazy border a mosaic of woods and meadows hides 18 protected plant species, some typical of mountains – a rarity on the upland.\n\nThe area is in the buffer zone of the Eagles’ Nests Landscape Park.'),
    accessible: false, accessNote: L('Leśne drogi.', 'Forest tracks.'), protection: L('Otulina Parku Krajobrazowego Orlich Gniazd', 'Buffer zone of the Eagles’ Nests Landscape Park'), tags: ['las', 'laka', 'rosliny'], ill: 'forest' },
  { id: 'laki-leka', name: L('Łąki Łęka', 'Łęka meadows'), kind: 'nature', scope: 'city', lat: 50.3820, lng: 19.3000, site: null, building: null, districtId: 'leka',
    short: L('Wilgotne łąki z reliktowymi dębami między nasypem kolejowym a ul. Łaskową.', 'Wet meadows with relict oaks between the railway embankment and ul. Łaskowa.'),
    description: L('Łąki w Łęce porastają pojedyncze stare dęby. Od kiedy zaprzestano koszenia, rzadkie gatunki stopniowo ustępują.\n\nTo dobry przykład, że niektóre siedliska przyrodnicze potrzebują człowieka.', 'Single old oaks stand in the Łęka meadows. Since mowing stopped, rare species have been slowly disappearing.\n\nIt shows that some habitats need people to survive.'),
    accessible: false, accessNote: L('Brak ścieżek utwardzonych.', 'No paved paths.'), protection: L('Otulina Parku Krajobrazowego Orlich Gniazd', 'Buffer zone of the Eagles’ Nests Landscape Park'), tags: ['laka', 'deby'], ill: 'tree' },
  { id: 'uroczysko-wypaleniska', name: L('Uroczysko Wypaleniska', 'Wypaleniska woodland'), kind: 'nature', scope: 'city', lat: 50.3770, lng: 19.3050, site: null, building: null, districtId: 'leka',
    short: L('Grądy i olsy z łąkami – 41 gatunków roślin chronionych lub rzadkich.', 'Oak-hornbeam and alder woods with meadows – 41 protected or rare plant species.'),
    description: L('Na południe od ul. Łaskowej rośnie las grądowy i olsowy przeplatany wilgotnymi łąkami. Botanicy naliczyli tu 41 gatunków chronionych lub rzadkich.\n\nWiosną warto przyjść tu na kwitnienie runa.', 'South of ul. Łaskowa grows oak-hornbeam and alder woodland mixed with wet meadows. Botanists have counted 41 protected or rare species here.\n\nCome in spring for the woodland flowers.'),
    accessible: false, accessNote: L('Leśne ścieżki.', 'Forest paths.'), protection: L('Otulina Parku Krajobrazowego Orlich Gniazd', 'Buffer zone of the Eagles’ Nests Landscape Park'), tags: ['las', 'grad', 'runo'], ill: 'forest' },
  { id: 'uroczysko-rudy', name: L('Uroczysko Rudy', 'Rudy woodland'), kind: 'nature', scope: 'city', lat: 50.3420, lng: 19.3800, site: null, building: null, districtId: 'okradzionow',
    short: L('Naturalna świetlista dąbrowa i wilgotne łąki z derkaczem.', 'Natural open oak woodland and wet meadows with corncrakes.'),
    description: L('Między Błędowem a Okradzionowem zachował się fragment świetlistej dąbrowy – lasu, w którym między dębami rośnie bujne, ciepłolubne runo. Na sąsiednich łąkach odzywa się derkacz.\n\nŁąki wymagają koszenia, by nie zarosły.', 'Between Błędów and Okradzionów survives a patch of open oak woodland with a rich, warmth-loving ground layer. Corncrakes call from the nearby meadows.\n\nThe meadows need mowing so they do not become overgrown.'),
    accessible: false, accessNote: L('Leśne drogi.', 'Forest tracks.'), protection: L('Otulina Parku Krajobrazowego Orlich Gniazd', 'Buffer zone of the Eagles’ Nests Landscape Park'), tags: ['dabrowa', 'derkacz', 'las'], ill: 'forest' },
  { id: 'przelom-bialej-przemszy', name: L('Przełom Białej Przemszy w Okradzionowie', 'Biała Przemsza gorge at Okradzionów'), kind: 'nature', scope: 'city', lat: 50.3320, lng: 19.3600, site: null, building: null, districtId: 'okradzionow',
    short: L('Wapienny przełom rzeki z zimnymi źródłami, starymi bukami i lessowymi wąwozami.', 'A limestone river gorge with cold springs, old beeches and loess ravines.'),
    description: L('Biała Przemsza przecina tu Garb Ząbkowicki, tworząc malowniczy przełom. Na zboczach rosną stare buki, a z dna wypływają zimne źródła.\n\nTo jedno z najbardziej „górskich” miejsc w mieście.', 'Here the Biała Przemsza cuts through the Ząbkowice Ridge, forming a picturesque gorge. Old beeches grow on the slopes and cold springs rise from the bottom.\n\nIt is one of the most “mountain-like” places in the city.'),
    accessible: false, accessNote: L('Strome zbocza.', 'Steep slopes.'), protection: L('Otulina Parku Krajobrazowego Orlich Gniazd', 'Buffer zone of the Eagles’ Nests Landscape Park'), tags: ['rzeka', 'przelom', 'buki'], ill: 'river' },
  { id: 'trzebieslawskie-wzgorza', name: L('Kompleks Trzebiesławskie Wzgórza', 'Trzebiesławice Hills complex'), kind: 'nature', scope: 'city', lat: 50.4100, lng: 19.2400, site: null, building: null, districtId: 'trzebieslawice',
    short: L('Bukowa Góra, Recki Las, Gródki, Stawki i Lasy Trzebiesławskie – lasy bukowe i murawy na północy miasta.', 'Bukowa Góra, Recki Las, Gródki, Stawki and the Trzebiesławice Forest – beech woods and grasslands in the north of the city.'),
    description: L('Na północnym krańcu miasta leży zespół wzgórz i lasów. Bukowa Góra kryje zbliżony do naturalnego las bukowy i jedyne w Polsce stanowiska wilczomlecza pstrego, w Reckim Lesie gniazduje kruk, a w Gródkach i Stawkach rozciągają się wilgotne łąki ze stawem.\n\nLasy Trzebiesławskie to rozległy las gospodarczy, w którym żyje wiele chronionych gatunków.', 'At the northern edge of the city lies a group of hills and woods. Bukowa Góra has near-natural beech forest and Poland’s only sites of the multicoloured spurge, ravens nest in Recki Las, and Gródki and Stawki have wet meadows and a pond.\n\nThe Trzebiesławice Forest is a large managed woodland home to many protected species.'),
    accessible: false, accessNote: L('Leśne drogi, strome podejścia.', 'Forest tracks, steep climbs.'), protection: null, tags: ['las', 'buki', 'wzgorza'], ill: 'forest' },
  { id: 'zbiornik-losien', name: L('Zbiornik Łosień', 'Łosień reservoir'), kind: 'nature', scope: 'city', lat: 50.3180, lng: 19.2600, site: null, building: null, districtId: 'losien',
    short: L('Kameralny zalew w Łosieniu – miejsce spacerów i wędkowania.', 'A small reservoir in Łosień – for walks and angling.'),
    description: L('Łosień wziął nazwę od dawnej puszczy łosieńskiej, której znaczną część wycięto w latach 70. pod budowę Huty Katowice. Zalew i otaczające go zadrzewienia to dziś zielona enklawa między osiedlami a kombinatem.\n\nW pobliżu rośnie pomnikowy jesion wyniosły.', 'Łosień takes its name from the old Łosień forest, much of which was cleared in the 1970s for Huta Katowice. The reservoir and its trees are now a green pocket between housing and the steel plant.\n\nA protected ash tree grows nearby.'),
    accessible: true, accessNote: L('Ścieżka wokół zbiornika częściowo utwardzona.', 'Path around the reservoir partly paved.'), protection: null, tags: ['woda', 'wedkowanie'], ill: 'lake' },
  { id: 'uroczysko-staszic', name: L('Uroczysko przy Staszicu', 'Staszic wasteland'), kind: 'nature', scope: 'city', lat: 50.3030, lng: 19.2700, site: null, building: null, districtId: 'strzemieszyce-male',
    short: L('Dawne tereny płytkiego górnictwa węgla, opanowane przez przyrodę; stawy z kumakiem nizinnym.', 'Former shallow coal-mining land taken over by nature; ponds with fire-bellied toads.'),
    description: L('W pobliżu skrzyżowania S1 i drogi nr 94 przyroda odzyskuje teren dawnych płytkich wyrobisk. W zapadliskach powstały stawy, w których żyje rzadki kumak nizinny.\n\nTo przykład wtórnej sukcesji – życia, które wraca na przemysłowe nieużytki.', 'Near the junction of the S1 and road 94 nature is reclaiming old shallow mine workings. Ponds formed in subsidence hollows now hold the rare European fire-bellied toad.\n\nIt is a textbook case of secondary succession on industrial wasteland.'),
    accessible: false, accessNote: L('Brak ścieżek.', 'No paths.'), protection: null, tags: ['sukcesja', 'plazy', 'gornictwo'], ill: 'wetland' },
  { id: 'gora-wielka', name: L('Zbocze pod Górą Wielką', 'Góra Wielka slope'), kind: 'nature', scope: 'city', lat: 50.3200, lng: 19.3200, site: null, building: null, districtId: 'strzemieszyce-wielkie',
    short: L('Murawa kserotermiczna z chronionymi roślinami między Strzemieszycami a Okradzionowem.', 'A dry grassland with protected plants between Strzemieszyce and Okradzionów.'),
    description: L('Nasłonecznione zachodnie zbocze porasta ciepłolubna murawa. Rosną tu chronione rośliny, ale rozprzestrzenia się inwazyjna trawa.\n\nLatem słychać tu mnóstwo pasikoników i świerszczy.', 'The sunny western slope is covered by warmth-loving grassland with protected plants, though an invasive grass is spreading.\n\nIn summer it is alive with grasshoppers and crickets.'),
    accessible: false, accessNote: L('Strome zbocze.', 'Steep slope.'), protection: null, tags: ['murawa', 'owady'], ill: 'forest' },
  { id: 'panska-gora', name: L('Pańska Góra', 'Pańska Góra'), kind: 'nature', scope: 'city', lat: 50.3950, lng: 19.2450, site: null, building: null, districtId: 'ujejsce',
    short: L('Wapienne ściany i murawy w pobliżu Ujejsca.', 'Limestone walls and grasslands near Ujejsce.'),
    description: L('Przy al. Zwycięstwa odsłaniają się ściany wapienne porośnięte murawami ciepłolubnymi. To jedno z miejsc, w których dobrze widać skalne podłoże Zagłębia.\n\nZ wierzchołka roztacza się widok na północną część miasta.', 'Near al. Zwycięstwa limestone walls covered with warmth-loving grassland are exposed – a good place to see the region’s bedrock.\n\nThe top offers a view over the northern part of the city.'),
    accessible: false, accessNote: L('Ścieżki skaliste.', 'Rocky paths.'), protection: null, tags: ['wapien', 'murawa', 'widok'], ill: 'quarry' },
  { id: 'kamieniolom-lady', name: L('Kamieniołom Łady', 'Łady quarry'), kind: 'nature', scope: 'city', lat: 50.3000, lng: 19.3100, site: null, building: null, districtId: 'strzemieszyce-wielkie',
    short: L('Odsłonięcie wapieni środkowego triasu pod lasem modrzewiowo-bukowym.', 'A Middle Triassic limestone exposure under larch and beech forest.'),
    description: L('Dawny kamieniołom w pobliżu Starosiedla odsłania warstwy wapienia sprzed ok. 240 mln lat. Las stopniowo zakrywa ściany, więc profil wymaga odsłaniania.\n\nW skałach można szukać skamieniałości dawnych organizmów morskich.', 'This old quarry near Starosiedle exposes limestone layers about 240 million years old. The forest is gradually hiding the walls, so the profile needs clearing.\n\nYou can look for fossils of ancient sea creatures in the rock.'),
    accessible: false, accessNote: L('Teren nierówny.', 'Uneven ground.'), protection: null, tags: ['geologia', 'trias', 'kamieniolom'], ill: 'quarry' },
  { id: 'szalasowizna', name: L('Szałasowizna i poldery Rakówki', 'Szałasowizna and the Rakówka polders'), kind: 'nature', scope: 'city', lat: 50.2950, lng: 19.2600, site: null, building: null, districtId: 'strzemieszyce-male',
    short: L('Poldery przeciwpowodziowe na południu miasta – żerowisko bocianów i ptaków wodnych.', 'Flood polders in the south of the city – feeding grounds for storks and waterbirds.'),
    description: L('Na pograniczu ze Sławkowem rozciągają się poldery Rakówki, okresowo zalewane wodą. Korzystają z nich ptaki wodne i płazy, a w okolicy Szałasowizny gniazdują bociany białe.\n\nW maju i czerwcu łatwo tu zobaczyć bociany żerujące na łąkach.', 'On the border with Sławków lie the Rakówka polders, periodically flooded. Waterbirds and amphibians use them, and white storks nest around Szałasowizna.\n\nIn May and June storks can easily be seen feeding in the meadows.'),
    accessible: false, accessNote: L('Drogi polne.', 'Field tracks.'), protection: null, tags: ['bociany', 'poldery', 'ptaki'], ill: 'wetland' },
  { id: 'las-bienia', name: L('Las Bienia', 'Bienia forest'), kind: 'nature', scope: 'city', lat: 50.3720, lng: 19.2950, site: null, building: null, districtId: 'sikorka',
    short: L('Sosnowy las na stoku od Łęki do Sikorki z rzadkimi roślinami leśnymi.', 'A pine forest on the slope from Łęka to Sikorka with rare woodland plants.'),
    description: L('W większości sadzony las sosnowy kryje rzadkie rośliny, takie jak dziewięćsił. To popularne miejsce spacerów mieszkańców Ząbkowic.\n\nPrzez las prowadzą ścieżki do Łęki.', 'This mostly planted pine forest hides rare plants such as the carline thistle. It is a favourite walking spot for Ząbkowice residents.\n\nPaths lead through the forest to Łęka.'),
    accessible: false, accessNote: L('Leśne ścieżki, piaszczyste.', 'Sandy forest paths.'), protection: null, tags: ['las', 'sosny'], ill: 'forest' },
  // ——— Pomniki przyrody ———
  { id: 'lipy-bugaj', name: L('Lipy drobnolistne w Bugaju', 'Small-leaved limes in Bugaj'), kind: 'tree', scope: 'city', lat: 50.3340, lng: 19.2230, site: null, building: null, districtId: 'bugaj',
    short: L('Para pomnikowych lip przy ul. Jałowcowej 15 – chroniona od 1954 r.', 'A pair of protected limes at ul. Jałowcowa 15 – protected since 1954.'),
    description: L('Dwie lipy drobnolistne należą do najstarszych pomników przyrody w mieście. Ich korony latem dają gęsty cień, a w czasie kwitnienia przyciągają pszczoły.\n\nDrzewa rosną przy prywatnej posesji – prosimy o oglądanie ich z ulicy.', 'These two small-leaved limes are among the city’s oldest natural monuments. In summer their crowns give deep shade and attract bees when in bloom.\n\nThe trees stand by a private property – please view them from the street.'),
    accessible: true, accessNote: L('Widoczne z chodnika.', 'Visible from the pavement.'), protection: L('Pomnik przyrody (1954)', 'Natural monument (1954)'), tags: ['drzewo', 'lipa', 'pomnik-przyrody'], ill: 'tree' },
  { id: 'lipy-dobieckich', name: L('„Lipy Dobieckich” w Kuźniczce Nowej', 'The “Dobiecki limes” in Kuźniczka Nowa'), kind: 'tree', scope: 'city', lat: 50.3550, lng: 19.3960, site: null, building: null, districtId: 'kuzniczka-nowa',
    short: L('Dwie lipy nad Białą Przemszą, chronione od 1958 r., nazwane od dawnych właścicieli majątku.', 'Two limes by the Biała Przemsza, protected since 1958 and named after the former estate owners.'),
    description: L('Lipy rosną nad Białą Przemszą w miejscu dawnego majątku. Nazwa przypomina rodzinę Dobieckich, z którą wiąże się historia okolicy.\n\nTo przystanek na długiej, rowerowej wersji trasy przyrodniczej.', 'The limes grow by the Biała Przemsza on the site of a former estate; their name recalls the Dobiecki family, linked with the area’s history.\n\nThey are a stop on the long cycling version of the nature trail.'),
    accessible: false, accessNote: L('Dojście drogą gruntową.', 'Access by dirt track.'), protection: L('Pomnik przyrody (1958)', 'Natural monument (1958)'), tags: ['drzewo', 'lipa', 'pomnik-przyrody'], ill: 'tree' },
  { id: 'jesion-losien', name: L('Jesion wyniosły w Łosieniu', 'Common ash in Łosień'), kind: 'tree', scope: 'city', lat: 50.3190, lng: 19.2530, site: null, building: null, districtId: 'losien',
    short: L('Okazały jesion przy ul. Łaskowej – pomnik przyrody.', 'A majestic ash tree on ul. Łaskowa – a natural monument.'),
    description: L('Jesion wyniosły to drzewo, którego populacje w Europie dziesiątkuje choroba grzybowa. Tym cenniejszy jest zdrowy, stary okaz w Łosieniu.\n\nZmierz obwód pnia w aplikacji i porównaj go z danymi z rejestru.', 'Ash populations across Europe are being devastated by a fungal disease, which makes this healthy old tree in Łosień all the more valuable.\n\nMeasure the trunk girth in the app and compare it with the register.'),
    accessible: true, accessNote: L('Przy chodniku.', 'Next to the pavement.'), protection: L('Pomnik przyrody', 'Natural monument'), tags: ['drzewo', 'jesion', 'pomnik-przyrody'], ill: 'tree' },
  { id: 'dab-wolnosci', name: L('„Dąb Wolności” w Parku Staszica', 'The “Freedom Oak” in Staszic Park'), kind: 'tree', scope: 'city', lat: 50.3200, lng: 19.1940, site: null, building: null, districtId: 'srodmiescie',
    short: L('Dąb szypułkowy posadzony w 1915 r., pomnik przyrody od 2004 r., w pobliżu „Sztygarki”.', 'A pedunculate oak planted in 1915, a natural monument since 2004, near the “Sztygarka” museum.'),
    description: L('Dąb rośnie w parku przy ul. Legionów Polskich i Górniczej, w sąsiedztwie dawnej szkoły górniczej. Posadzono go w 1915 r., w czasie I wojny światowej, a jego nazwa nawiązuje do dążeń niepodległościowych.\n\nDziś jest jednym z najbardziej symbolicznych drzew w mieście.', 'The oak grows in the park by ul. Legionów Polskich and ul. Górnicza, next to the old mining school. It was planted in 1915, during the First World War, and its name refers to the hopes for independence.\n\nToday it is one of the city’s most symbolic trees.'),
    accessible: true, accessNote: L('Alejki parkowe utwardzone.', 'Paved park paths.'), protection: L('Pomnik przyrody (2004)', 'Natural monument (2004)'), tags: ['drzewo', 'dab', 'pomnik-przyrody', 'niepodleglosc'], ill: 'tree' },
  { id: 'bozodrzew-sikorka', name: L('Bożodrzewy w Sikorce', 'Trees of heaven in Sikorka'), kind: 'tree', scope: 'city', lat: 50.3610, lng: 19.2830, site: null, building: null, districtId: 'sikorka',
    short: L('Dwa bożodrzewy przy ul. Hallerczyków 165, chronione od 2007 r.', 'Two trees of heaven at ul. Hallerczyków 165, protected since 2007.'),
    description: L('Bożodrzew gruczołowaty pochodzi z Chin; w XIX i XX w. sadzono go w miastach przemysłowych, bo dobrze znosi zanieczyszczenia. Para okazów w Sikorce osiągnęła wyjątkowe rozmiary.\n\nTo dobry pretekst do rozmowy o gatunkach obcych – dziś bożodrzew uchodzi za inwazyjny.', 'The tree of heaven comes from China; in the 19th and 20th centuries it was planted in industrial towns because it tolerates pollution. This pair in Sikorka has grown exceptionally large.\n\nIt is a good starting point for talking about alien species – the tree is now considered invasive.'),
    accessible: true, accessNote: L('Widoczne z chodnika.', 'Visible from the pavement.'), protection: L('Pomnik przyrody (2007)', 'Natural monument (2007)'), tags: ['drzewo', 'bozodrzew', 'pomnik-przyrody'], ill: 'tree' },
  // ——— Parki ———
  { id: 'park-hallera', name: L('Park Hallera', 'Haller Park'), kind: 'park', scope: 'city', lat: 50.3250, lng: 19.1830, site: null, building: null, districtId: 'srodmiescie',
    short: L('Śródmiejski park w pobliżu Fabryki Pełnej Życia – zielony łącznik nowego centrum.', 'A city-centre park near the Factory – a green link for the new centre.'),
    description: L('Park im. gen. Józefa Hallera leży w centrum miasta, niedaleko terenu FPŻ. Koncepcja nowego śródmieścia zakłada powiązanie go pieszymi ścieżkami z Fabryką i placem przed Pałacem Kultury Zagłębia.\n\nTo pierwszy przystanek krótkiej trasy przyrodniczej.', 'Park named after General Józef Haller lies in the city centre, not far from the Factory site. The new centre plan links it by footpaths with the Factory and the square in front of the Palace of Culture.\n\nIt is the first stop on the short nature trail.'),
    accessible: true, accessNote: L('Alejki asfaltowe, ławki, toaleta w pobliżu.', 'Asphalt paths, benches, toilet nearby.'), protection: null, tags: ['park', 'centrum'], ill: 'park' },
  { id: 'park-zielona', name: L('Park Zielona', 'Zielona Park'), kind: 'park', scope: 'city', lat: 50.3160, lng: 19.2240, site: null, building: null, districtId: 'mydlice',
    short: L('Największy park miasta (ok. 67 ha), założony w 1932 r., z uroczyskiem chronionym jako użytek ekologiczny.', 'The city’s largest park (about 67 ha), founded in 1932, with a woodland protected as an ecological site.'),
    description: L('Park założono w 1932 r. w dawnym lesie. Jego wschodnia część – ok. 17,5 ha zbliżonego do naturalnego grądu – od 2008 r. jest użytkiem ekologicznym „Uroczysko Zielona”.\n\nW parku są stawy, place zabaw i ścieżki rowerowe, a wiosną kwitnie bogate runo.', 'The park was laid out in 1932 in an old forest. Its eastern part – about 17.5 ha of near-natural oak-hornbeam woodland – has been the “Uroczysko Zielona” ecological site since 2008.\n\nThere are ponds, playgrounds and cycle paths, and in spring a rich carpet of woodland flowers.'),
    accessible: true, accessNote: L('Główne alejki utwardzone, dostępne toalety przy wejściu.', 'Main paths paved, accessible toilets at the entrance.'), protection: L('Użytek ekologiczny „Uroczysko Zielona” (2008, część wschodnia)', '“Uroczysko Zielona” ecological site (2008, eastern part)'), tags: ['park', 'las', 'uzytek'], ill: 'park' },
  { id: 'park-podlesie', name: L('Park Podlesie', 'Podlesie Park'), kind: 'park', scope: 'city', lat: 50.3110, lng: 19.1950, site: null, building: null, districtId: 'korzeniec',
    short: L('Leśny park odnawiany w ramach projektu „Park Podlesie Pełne Życia”.', 'A woodland park being renewed under the “Podlesie Park Full of Life” project.'),
    description: L('Park o leśnym charakterze objęto projektem „Park Podlesie Pełne Życia”, którego koncepcję pokazano mieszkańcom w 2020 r. Program obejmuje nowe ścieżki, miejsca odpoczynku i strefy aktywności przy zachowaniu leśnego drzewostanu.\n\nNazwa projektu nawiązuje do Fabryki Pełnej Życia – zieleń i nowe centrum mają tworzyć jedną sieć.', 'This woodland-style park is covered by the “Podlesie Park Full of Life” project, whose concept was presented to residents in 2020. It brings new paths, rest areas and activity zones while keeping the forest stand.\n\nThe name echoes the Factory Full of Life – greenery and the new centre are meant to form one network.'),
    accessible: true, accessNote: L('Utwardzone alejki główne.', 'Paved main paths.'), protection: null, tags: ['park', 'budzet-obywatelski'], ill: 'forest' },
];

const heritage = [
  // ——— Dziedzictwo przemysłowe ———
  { id: 'kopalnia-reden', name: L('Kopalnia Reden (miejsce dawnej kopalni)', 'Reden mine (former site)'), kind: 'industry', scope: 'city', lat: 50.3245, lng: 19.1920, site: null, building: null, districtId: 'srodmiescie',
    short: L('Pierwsza kopalnia węgla w Dąbrowie (1796) – obiekt nieistniejący, ślady w nazwach i pod ziemią.', 'The first coal mine in Dąbrowa (1796) – no longer standing; traces survive in names and underground.'),
    description: L('Kopalnię założono w 1796 r. na wychodniach pokładów węgla i nazwano na cześć pruskiego dyrektora górnictwa Friedricha Wilhelma von Redena. Przez pierwsze lata węgiel wydobywano odkrywkowo – ok. 200 ton rocznie. W 1807 r. kopalnia przeszła w ręce marszałka Lannes’a, a w 1814 r. przejął ją skarb państwa.\n\n**Obiekt nie istnieje**, ale pod budynkiem dawnej Resursy kończyła się sztolnia odwadniająca, w której od 1824 r. pracowała maszyna parowa. Nazwa „Reden” żyje w nazwie dzielnicy i pasażu na terenie FPŻ.', 'The mine was founded in 1796 on coal-seam outcrops and named after the Prussian mining director Friedrich Wilhelm von Reden. In its first years coal was dug in the open – about 200 tonnes a year. In 1807 it passed to Marshal Lannes, and in 1814 the state treasury took it over.\n\n**The mine no longer exists**, but a drainage adit ended under the former Resursa building, where a steam engine worked from 1824. The name “Reden” lives on in a district and in a passage at the Factory.'),
    accessible: true, accessNote: L('Punkt narracyjny przy chodniku.', 'Storytelling point by the pavement.'), protection: null, tags: ['kopalnia', 'wegiel', 'nieistniejace', 'xviii-wiek'], ill: 'mine' },
  { id: 'kopalnia-cwiczebna', name: L('Kopalnia Ćwiczebna Muzeum „Sztygarka”', 'Sztygarka Training Mine'), kind: 'industry', scope: 'city', lat: 50.3205, lng: 19.1955, site: null, building: null, districtId: 'srodmiescie',
    short: L('Szkolna kopalnia z lat 1927–1929, od 2010 r. podziemna trasa turystyczna.', 'A school mine built in 1927–1929, open as an underground tourist route since 2010.'),
    description: L('Budowę kopalni ćwiczebnej dla Państwowej Szkoły Górniczej i Hutniczej rozpoczęto w kwietniu 1927 r., a pierwszy etap ukończono w 1929 r. Uczniowie ćwiczyli tu aż do 1994 r. Wyrobiska mają trzy poziomy i odsłaniają dwa pokłady węgla.\n\nOd 2 stycznia 2010 r. kopalnia jest udostępniona zwiedzającym: można zobaczyć ścianę węglową z kombajnem, obudowy górnicze i rozdzielnię elektryczną.', 'Construction of the training mine for the State Mining and Metallurgy School began in April 1927, and the first stage was finished in 1929. Students trained here until 1994. The workings are on three levels and expose two coal seams.\n\nSince 2 January 2010 the mine has been open to visitors, who can see a coal face with a shearer, roof supports and an electrical switchgear room.'),
    accessible: false, accessNote: L('Trasa podziemna ze schodami i nachylonymi wyrobiskami – niedostępna dla wózków; prezentacja multimedialna na powierzchni.', 'Underground route with stairs and inclines – not wheelchair accessible; multimedia show above ground.'), protection: null, tags: ['kopalnia', 'muzeum', 'edukacja'], ill: 'mine' },
  { id: 'kopalnia-paryz', name: L('Kopalnia „Paryż”', '“Paryż” colliery'), kind: 'industry', scope: 'city', lat: 50.3270, lng: 19.2080, site: null, building: null, districtId: 'reden',
    short: L('Jedna z największych kopalń miasta; po wojnie „Generał Zawadzki”, zamknięta w 1995 r.', 'One of the city’s largest collieries; after the war named “Generał Zawadzki”, closed in 1995.'),
    description: L('Obszar górniczy kopalni obejmował ok. 27 km² w Dąbrowie, Będzinie i Sosnowcu. W okresie PRL nosiła nazwę „Generał Zawadzki”; w 1965 r. jej wydobycie przewyższało roczne wydobycie węgla kamiennego całej NRD.\n\nLikwidację rozpoczęto w 1993 r., wydobycie zakończono 30 czerwca 1995 r. Nazwa „Paryż” przypomina francuski kapitał, który w XIX w. inwestował w zagłębiowskie górnictwo.', 'The mine’s concession covered about 27 km² across Dąbrowa, Będzin and Sosnowiec. In communist times it was called “Generał Zawadzki”; in 1965 its output exceeded the entire hard-coal production of East Germany.\n\nLiquidation began in 1993 and mining ended on 30 June 1995. The name “Paryż” recalls the French capital that invested in the region’s mining in the 19th century.'),
    accessible: true, accessNote: L('Punkt narracyjny przy drodze.', 'Storytelling point by the road.'), protection: null, tags: ['kopalnia', 'wegiel', 'prl'], ill: 'mine' },
  { id: 'huta-bankowa', name: L('Huta Bankowa', 'Huta Bankowa steelworks'), kind: 'industry', scope: 'city', lat: 50.3180, lng: 19.2050, site: null, building: null, districtId: 'korzeniec',
    short: L('Huta budowana od 1834 r. z kapitałem Banku Polskiego – działa do dziś.', 'A steelworks built from 1834 with Bank Polski capital – still operating today.'),
    description: L('Budowę huty rozpoczęto w 1834 r., a nazwę zawdzięcza Bankowi Polskiemu, który sfinansował inwestycję. Była jednym z filarów przemysłu Królestwa Polskiego, a w latach 1950–1989 działała jako Huta im. Feliksa Dzierżyńskiego.\n\nHuta Bankowa pracuje nadal – to jeden z najstarszych czynnych zakładów hutniczych w Polsce.', 'Construction began in 1834, and the works owe their name to Bank Polski, which financed the project. It was a pillar of industry in the Kingdom of Poland, and from 1950 to 1989 operated as the Feliks Dzierżyński Steelworks.\n\nHuta Bankowa is still running – one of the oldest active steelworks in Poland.'),
    accessible: true, accessNote: L('Oglądanie z zewnątrz; teren zakładu niedostępny.', 'View from outside; the plant is closed to visitors.'), protection: null, tags: ['huta', 'stal', 'xix-wiek'], ill: 'steelworks' },
  { id: 'huta-katowice', name: L('Huta Katowice (kombinat)', 'Huta Katowice steel plant'), kind: 'industry', scope: 'city', lat: 50.3050, lng: 19.2950, site: null, building: null, districtId: 'strzemieszyce-male',
    short: L('Sztandarowa inwestycja PRL: budowa od 1972 r., pierwszy wielki piec w 1976 r.', 'The flagship investment of communist Poland: built from 1972, first blast furnace lit in 1976.'),
    description: L('Budowę kombinatu rozpoczęto 15 kwietnia 1972 r., a 2 grudnia 1976 r. uruchomiono wielki piec. Przy budowie pracowało ponad 50 tys. osób z całej Polski, dla których wyrosły nowe osiedla. Pod zakład wycięto ponad 820 ha puszczy łosieńskiej.\n\nHuta zmieniła Dąbrowę Górniczą w jedno z największych miast regionu; dziś działa pod inną nazwą, ale przystanek tramwajowy wciąż nazywa się „Huta Katowice”.', 'Construction began on 15 April 1972, and the blast furnace was lit on 2 December 1976. More than 50,000 people from all over Poland worked on the site, and new housing estates grew up for them. Over 820 ha of the Łosień forest were felled for the plant.\n\nThe steelworks turned Dąbrowa Górnicza into one of the region’s largest cities; it now operates under another name, but the tram stop is still called “Huta Katowice”.'),
    accessible: true, accessNote: L('Punkt widokowy przy przystanku tramwajowym.', 'Viewpoint at the tram stop.'), protection: null, tags: ['huta', 'prl', 'kombinat'], ill: 'steelworks' },
  { id: 'koksownia-przyjazn', name: L('Koksownia „Przyjaźń”', '“Przyjaźń” coking plant'), kind: 'industry', scope: 'city', lat: 50.2980, lng: 19.3050, site: null, building: null, districtId: 'strzemieszyce-male',
    short: L('Duża koksownia powiązana z kombinatem hutniczym w południowo-wschodniej części miasta.', 'A large coking plant linked to the steel complex in the south-east of the city.'),
    description: L('Koks to paliwo wielkiego pieca – bez niego nie da się wytopić surówki. Koksownia w sąsiedztwie kombinatu powstała jako część wielkiego zagłębia hutniczego lat 70.\n\nNa trasie przemysłowej to przystanek, na którym poznajemy łańcuch: węgiel – koks – surówka – stal.', 'Coke fuels the blast furnace – without it no pig iron can be made. The coking plant next to the steel complex was built as part of the great 1970s steel development.\n\nOn the industry trail this stop explains the chain: coal – coke – pig iron – steel.'),
    accessible: true, accessNote: L('Oglądanie z drogi publicznej.', 'View from the public road.'), protection: null, tags: ['koks', 'prl', 'hutnictwo'], ill: 'steelworks' },
  { id: 'dworzec-dabrowa', name: L('Dworzec Dąbrowa Górnicza', 'Dąbrowa Górnicza railway station'), kind: 'industry', scope: 'city', lat: 50.3300, lng: 19.1856, site: null, building: null, districtId: 'srodmiescie',
    short: L('Stacja na linii dawnej Kolei Warszawsko-Wiedeńskiej, sąsiad terenu FPŻ.', 'A station on the former Warsaw–Vienna Railway, next door to the Factory.'),
    description: L('Około 1910 r. węzeł kolejowy przesunięto bliżej linii warszawsko-wiedeńskiej, a dworzec stał się bramą do miasta. Bliskość torów zdecydowała o lokalizacji fabryki – zakład wyrósł z budynków stacyjnych stojących tu od 1885 r.\n\nPeron przebudowano w 2022 r.; dziś to główne wejście do Fabryki dla osób przyjeżdżających pociągiem.', 'Around 1910 the rail junction moved closer to the Warsaw–Vienna line, and the station became the gateway to the town. Proximity to the tracks shaped the factory’s location – the works grew out of station buildings that had stood here since 1885.\n\nThe platform was rebuilt in 2022; today it is the main way into the Factory for visitors arriving by train.'),
    accessible: true, accessNote: L('Peron z windą/pochylnią, dojście chodnikiem do FPŻ (ok. 300 m).', 'Platform with lift/ramp, pavement access to the Factory (about 300 m).'), protection: null, tags: ['kolej', 'dworzec'], ill: 'railway' },
  { id: 'dworzec-zabkowice', name: L('Dworzec Dąbrowa Górnicza Ząbkowice', 'Dąbrowa Górnicza Ząbkowice station'), kind: 'industry', scope: 'city', lat: 50.3683, lng: 19.2669, site: null, building: null, districtId: 'zabkowice',
    short: L('Pierwszy pociąg z Warszawy dotarł tu w grudniu 1847 r.; budynek dworca ukończono w 1856 r.', 'The first train from Warsaw arrived in December 1847; the station building was finished in 1856.'),
    description: L('Kolej Warszawsko-Wiedeńska była pierwszą linią kolejową na ziemiach zaboru rosyjskiego. Pierwszy pociąg dotarł do Ząbkowic w grudniu 1847 r., a rok później linia osiągnęła granicę rosyjsko-austriacką. Budynek dworca ukończono w 1856 r.\n\nW 1859 r. Ząbkowice stały się węzłem, gdy otwarto tor przez Będzin i Sosnowiec do Katowic.', 'The Warsaw–Vienna Railway was the first railway in the Russian partition. The first train reached Ząbkowice in December 1847, and a year later the line reached the Russian–Austrian border. The station building was completed in 1856.\n\nIn 1859 Ząbkowice became a junction when the line via Będzin and Sosnowiec to Katowice opened.'),
    accessible: true, accessNote: L('Dostęp do budynku z poziomu chodnika.', 'Building reachable from pavement level.'), protection: null, tags: ['kolej', 'dworzec', 'xix-wiek'], ill: 'railway' },
  { id: 'huta-szkla-zabkowice', name: L('Huta Szkła Ząbkowice', 'Ząbkowice Glassworks'), kind: 'industry', scope: 'city', lat: 50.3700, lng: 19.2720, site: null, building: null, districtId: 'zabkowice',
    short: L('Huta założona w 1884 r., słynna ze szkła prasowanego; zamknięta w 2004 r.', 'A glassworks founded in 1884, famous for pressed glass; closed in 2004.'),
    description: L('Hutę założył w 1884 r. Józef Schreiber; w 1896 r. przekształcono ją w spółkę akcyjną. Od 1902 r. produkowano tu szkło prasowane – patery, wazony, świeczniki – a po 1945 r. wzory projektowali m.in. Eryka Trzewik-Drost i Jan Sylwester Drost.\n\nProdukcję przerwał wielki kryzys (1935), wznowiono ją jednak i trwała aż do upadłości w 2004 r. Dziś ząbkowickie szkło jest poszukiwane przez kolekcjonerów.', 'The glassworks was founded in 1884 by Józef Schreiber and became a joint-stock company in 1896. From 1902 it made pressed glass – cake stands, vases, candlesticks – and after 1945 designs came from Eryka Trzewik-Drost and Jan Sylwester Drost, among others.\n\nThe Great Depression halted production in 1935, but it resumed and continued until bankruptcy in 2004. Today Ząbkowice glass is sought after by collectors.'),
    accessible: true, accessNote: L('Punkt narracyjny przy ulicy.', 'Storytelling point by the street.'), protection: null, tags: ['szklo', 'design', 'xix-wiek'], ill: 'glassworks' },
  { id: 'lhs', name: L('Linia Hutnicza Szerokotorowa', 'Broad Gauge Metallurgy Line (LHS)'), kind: 'industry', scope: 'city', lat: 50.3040, lng: 19.3300, site: null, building: null, districtId: 'strzemieszyce-wielkie',
    short: L('Najdalej na zachód sięgająca linia o rozstawie szyn 1520 mm, zbudowana dla kombinatu.', 'The westernmost 1520 mm broad-gauge line, built to serve the steel plant.'),
    description: L('Linia szerokotorowa łączy granicę z Ukrainą z rejonem Sławkowa i kombinatu. Zbudowano ją, by bez przeładunku dowozić rudę żelaza ze wschodu do huty.\n\nDziś służy przewozom towarowym, a jej terminal w sąsiednim Sławkowie jest ważnym węzłem logistycznym.', 'The broad-gauge line links the Ukrainian border with the Sławków area and the steel plant. It was built to bring iron ore from the east without transhipment.\n\nToday it carries freight, and its terminal in neighbouring Sławków is a major logistics hub.'),
    accessible: true, accessNote: L('Punkt widokowy przy wiadukcie.', 'Viewpoint by the viaduct.'), protection: null, tags: ['kolej', 'prl', 'logistyka'], ill: 'railway' },
  { id: 'kopalnia-kazimierz-juliusz', name: L('Kopalnia „Kazimierz-Juliusz” (Sosnowiec)', '“Kazimierz-Juliusz” colliery (Sosnowiec)'), kind: 'industry', scope: 'city', lat: 50.2880, lng: 19.2380, site: null, building: null, districtId: null,
    short: L('Ostatnia czynna kopalnia Zagłębia Dąbrowskiego, zamknięta w 2015 r.', 'The last working colliery in the Dąbrowa Basin, closed in 2015.'),
    description: L('Kopalnia w Sosnowcu-Kazimierzu była ostatnim zakładem górniczym zagłębiowskiej części regionu. Uroczystość wydobycia ostatniej tony węgla zakończyła ponad dwa stulecia górnictwa w Zagłębiu.\n\nTo dobry punkt na zakończenie wątku „kopalnie” – i pretekst do rozmowy o sprawiedliwej transformacji.', 'The mine in Sosnowiec-Kazimierz was the last colliery in the Zagłębie part of the region. The ceremony of hoisting the last tonne of coal closed more than two centuries of mining in the Basin.\n\nIt is a fitting end to the “mines” thread – and a starting point for talking about a just transition.'),
    accessible: true, accessNote: L('Oglądanie z zewnątrz.', 'View from outside.'), protection: null, tags: ['kopalnia', 'transformacja'], ill: 'mine' },
  { id: 'palac-schoena', name: L('Pałac Schoena (Sosnowiec)', 'Schoen Palace (Sosnowiec)'), kind: 'industry', scope: 'city', lat: 50.2840, lng: 19.1440, site: null, building: null, districtId: null,
    short: L('Rezydencja rodziny fabrykantów włókienniczych – dziś muzeum; ślad zagłębiowskiego włókiennictwa.', 'The residence of a textile-mill family – now a museum; a trace of the Basin’s textile industry.'),
    description: L('Zagłębie to nie tylko węgiel i stal. W XIX w. w Sosnowcu działały duże przędzalnie, a rodzina Schoenów należała do najważniejszych fabrykantów włókienniczych. Ich dawna rezydencja służy dziś jako muzeum.\n\nWłókiennictwo dawało pracę kobietom i współtworzyło przemysłowy krajobraz regionu.', 'The Basin was not only coal and steel. In the 19th century large spinning mills operated in Sosnowiec, and the Schoen family were among the leading textile manufacturers. Their former residence is now a museum.\n\nTextiles gave work to women and helped shape the region’s industrial landscape.'),
    accessible: true, accessNote: L('Informacje o dostępności – na stronie muzeum.', 'Accessibility details on the museum’s website.'), protection: null, tags: ['wlokiennictwo', 'muzeum', 'xix-wiek'], ill: 'palace' },
  { id: 'zawiercie-taz', name: L('Dawne zakłady włókiennicze w Zawierciu', 'Former textile mills in Zawiercie'), kind: 'industry', scope: 'city', lat: 50.4900, lng: 19.4200, site: null, building: null, districtId: null,
    short: L('Osiedle i fabryka Towarzystwa Akcyjnego „Zawiercie” – zagłębiowskie włókiennictwo na północy regionu.', 'The mill and housing of the “Zawiercie” joint-stock company – textiles in the north of the region.'),
    description: L('Zawiercie wyrosło w XIX w. wokół wielkich zakładów bawełnianych. Przy fabryce powstały domy robotnicze, szkoła i szpital – typowy przykład przemysłowego miasta-osiedla.\n\nPrzystanek na trasie dla tych, którzy chcą pojechać dalej koleją z Ząbkowic.', 'Zawiercie grew in the 19th century around large cotton mills. Workers’ housing, a school and a hospital were built next to the factory – a typical industrial company town.\n\nA stop for those who want to travel on by train from Ząbkowice.'),
    accessible: true, accessNote: L('Spacer ulicami osiedla.', 'A walk along the estate streets.'), protection: null, tags: ['wlokiennictwo', 'osiedle', 'kolej'], ill: 'factory-archival' },
  { id: 'kuznice-bialej-przemszy', name: L('Dawne kuźnice nad Białą Przemszą', 'Old forges on the Biała Przemsza'), kind: 'industry', scope: 'city', lat: 50.3560, lng: 19.3900, site: null, building: null, districtId: 'kuzniczka-nowa',
    short: L('Nazwa Kuźniczki przypomina wodne kuźnice – rzemiosło, które poprzedziło wielki przemysł.', 'The name Kuźniczka recalls water-powered forges – a craft that came before heavy industry.'),
    description: L('Zanim powstały kopalnie i huty, nad rzekami Zagłębia pracowały małe kuźnice napędzane kołami wodnymi. Kowale, ślusarze i cieśle tworzyli później otoczenie dla wielkiego przemysłu – także dla dąbrowskiego warsztatu, z którego wyrósł DEFUM.\n\n(Opis ogólny – brak zachowanych obiektów kuźniczych w terenie.)', 'Before mines and steelworks, small water-wheel forges worked on the region’s rivers. Blacksmiths, locksmiths and carpenters later formed the backdrop for heavy industry – including the Dąbrowa workshop that grew into DEFUM.\n\n(General description – no forge buildings survive on site.)'),
    accessible: false, accessNote: L('Brak udogodnień.', 'No facilities.'), protection: null, tags: ['rzemioslo', 'kuznia', 'nieistniejace'], ill: 'workshop' },
  { id: 'elektrownia-lagisza', name: L('Elektrownia Łagisza (Będzin)', 'Łagisza power station (Będzin)'), kind: 'industry', scope: 'city', lat: 50.3500, lng: 19.1350, site: null, building: null, districtId: null,
    short: L('Elektrownia węglowa na granicy z Dąbrową – część energetycznego zaplecza Zagłębia.', 'A coal-fired power station on the Dąbrowa border – part of the Basin’s energy base.'),
    description: L('Kominy elektrowni widać z wielu miejsc w Dąbrowie Górniczej. Zakład przetwarza węgiel na prąd i ciepło dla regionu.\n\nNa trasie przemysłowej to przystanek o energetyce i o tym, jak region szuka dziś czystszych źródeł energii.', 'The power station’s chimneys can be seen from many places in Dąbrowa Górnicza. It turns coal into electricity and heat for the region.\n\nOn the industry trail this stop is about energy and how the region is now looking for cleaner sources.'),
    accessible: true, accessNote: L('Oglądanie z zewnątrz.', 'View from outside.'), protection: null, tags: ['energetyka', 'wegiel'], ill: 'steelworks' },
  // ——— Historia i kultura ———
  { id: 'palac-kultury-zaglebia', name: L('Pałac Kultury Zagłębia', 'Pałac Kultury Zagłębia (Zagłębie Palace of Culture)'), kind: 'culture', scope: 'city', lat: 50.3262, lng: 19.1884, site: null, building: null, districtId: 'srodmiescie',
    short: L('Socrealistyczny pałac (1951–1958, proj. Zbigniew Rzepecki) – główna instytucja kultury miasta.', 'A socialist-realist palace (1951–1958, by Zbigniew Rzepecki) – the city’s main cultural institution.'),
    description: L('Budowę rozpoczęto w maju 1951 r., a uroczyste otwarcie odbyło się 11 stycznia 1958 r. Gmach z wieżą zwieńczoną attykami zaprojektował Zbigniew Rzepecki. Mieści sale widowiskowe, galerie i pracownie.\n\nPałac sąsiaduje z terenem FPŻ – koncepcja nowego centrum przewiduje plac przed jego fasadą i ciąg pieszo-rowerowy do Fabryki.', 'Construction began in May 1951 and the official opening took place on 11 January 1958. The building with its attic-crowned tower was designed by Zbigniew Rzepecki and houses auditoriums, galleries and studios.\n\nThe Palace is next to the Factory site – the new centre plan includes a square in front of it and a walking and cycling route to the Factory.'),
    accessible: true, accessNote: L('Wejście z pochylnią, winda.', 'Ramped entrance, lift.'), protection: null, tags: ['kultura', 'socrealizm', 'prl'], ill: 'palace' },
  { id: 'bazylika', name: L('Bazylika Matki Boskiej Anielskiej', 'Basilica of Our Lady of the Angels'), kind: 'history', scope: 'city', lat: 50.3225, lng: 19.1905, site: null, building: null, districtId: 'srodmiescie',
    short: L('Neogotycka świątynia (kamień węgielny 1898, proj. Józef Pomian-Pomianowski) – „katedra Zagłębia”.', 'A neo-Gothic church (foundation stone 1898, by Józef Pomian-Pomianowski) – the “cathedral of the Basin”.'),
    description: L('Kamień węgielny poświęcono 2 sierpnia 1898 r., a halowy, trzynawowy kościół zaprojektował Józef Pomian-Pomianowski. W 1901 r. papież Leon XIII nadał świątyni przywileje bazyliki.\n\nW 1968 r. odwiedzili ją kard. Stefan Wyszyński i kard. Karol Wojtyła.', 'The foundation stone was blessed on 2 August 1898, and the three-nave hall church was designed by Józef Pomian-Pomianowski. In 1901 Pope Leo XIII granted it the privileges of a basilica.\n\nIn 1968 it was visited by Cardinals Stefan Wyszyński and Karol Wojtyła.'),
    accessible: true, accessNote: L('Wejście boczne z pochylnią.', 'Side entrance with a ramp.'), protection: null, tags: ['kosciol', 'neogotyk', 'xix-wiek'], ill: 'church' },
  { id: 'muzeum-sztygarka', name: L('Muzeum Miejskie „Sztygarka”', '“Sztygarka” City Museum'), kind: 'culture', scope: 'city', lat: 50.3210, lng: 19.1945, site: null, building: null, districtId: 'srodmiescie',
    short: L('Muzeum w gmachu dawnej szkoły górniczej (1889) – geologia, górnictwo i historia miasta.', 'A museum in the old mining school (1889) – geology, mining and city history.'),
    description: L('Szkołę Górniczą, nazywaną „Sztygarką”, otwarto 1 lutego 1889 r. w budynku z 1842 r. Po przerwie od 1905 r. wznowiła działalność w 1919 r. jako Państwowa Szkoła Górnicza i Hutnicza. Muzeum Miejskie „Sztygarka” powołano w 1997 r., kontynuując tradycje muzeum otwartego w 1912 r.\n\nW muzeum zobaczysz zbiory geologiczne i pamiątki górnicze, a obok wejdziesz do Kopalni Ćwiczebnej.', 'The Mining School, known as “Sztygarka”, opened on 1 February 1889 in a building from 1842. After a break from 1905 it reopened in 1919 as the State Mining and Metallurgy School. The “Sztygarka” City Museum was established in 1997, continuing the traditions of a museum opened in 1912.\n\nInside you will find geological collections and mining memorabilia, and next door you can enter the Training Mine.'),
    accessible: true, accessNote: L('Parter dostępny; piętra – sprawdź na miejscu.', 'Ground floor accessible; upper floors – check on site.'), protection: null, tags: ['muzeum', 'gornictwo', 'edukacja'], ill: 'mine' },
  { id: 'resursa', name: L('Resursa', 'Resursa building'), kind: 'history', scope: 'city', lat: 50.3240, lng: 19.1915, site: null, building: null, districtId: 'srodmiescie',
    short: L('Dawny klub obywatelski nad wylotem sztolni kopalni Reden; tu w 1912 r. otwarto muzeum.', 'A former civic club above the Reden mine adit; a museum opened here in 1912.'),
    description: L('Pod budynkiem Resursy kończyła się sztolnia odwadniająca kopalni Reden, w której od 1824 r. pracowała maszyna parowa. W Resursie 6 sierpnia 1912 r. otwarto muzeum im. Zygmunta Glogera, a w 1918 r. przed budynkiem wojsko rozpędziło demonstrację.\n\nTo miejsce, w którym splatają się historia górnictwa, kultury i walki o prawa robotnicze.', 'The Reden mine drainage adit ended beneath the Resursa building, where a steam engine pumped water from 1824. On 6 August 1912 the Zygmunt Gloger Museum opened in the Resursa, and in 1918 troops broke up a demonstration outside.\n\nHere the histories of mining, culture and workers’ rights intertwine.'),
    accessible: true, accessNote: L('Punkt narracyjny przy chodniku.', 'Storytelling point by the pavement.'), protection: null, tags: ['historia', 'reden', 'muzeum'], ill: 'city-street' },
  { id: 'dworzec-iwangorodzki', name: L('Dawny dworzec Kolei Iwanogrodzko-Dąbrowskiej', 'Former Ivangorod–Dąbrowa Railway station'), kind: 'history', scope: 'city', lat: 50.3255, lng: 19.1895, site: null, building: null, districtId: 'srodmiescie',
    short: L('Nieistniejący parterowy dworzec w pobliżu dzisiejszego Placu Wolności.', 'A lost single-storey station near today’s Plac Wolności.'),
    description: L('Kolej Iwanogrodzko-Dąbrowska połączyła Zagłębie z centralną Rosją w 1885 r. W pobliżu dzisiejszego Placu Wolności stał niewielki ceglany dworzec. Ok. 1910 r. węzeł przeniesiono w stronę linii warszawsko-wiedeńskiej, a zniszczony w czasie wojny budynek rozebrano przy budowie placu.\n\n**Obiekt nie istnieje** – w aplikacji AR zobaczysz jego rekonstrukcję.', 'The Ivangorod–Dąbrowa Railway linked the Basin with central Russia in 1885. A small brick station stood near today’s Plac Wolności. Around 1910 the junction moved towards the Warsaw–Vienna line, and the war-damaged building was demolished when the square was laid out.\n\n**The building no longer exists** – the AR view shows a reconstruction.'),
    accessible: true, accessNote: L('Plac z równą nawierzchnią.', 'Square with level paving.'), protection: null, tags: ['kolej', 'nieistniejace', 'ar'], ill: 'railway' },
  { id: 'plac-wolnosci', name: L('Plac Wolności i Pomnik Bohaterów Czerwonych Sztandarów', 'Plac Wolności and the Heroes of the Red Banners monument'), kind: 'history', scope: 'city', lat: 50.3255, lng: 19.1880, site: null, building: null, districtId: 'srodmiescie',
    short: L('Reprezentacyjny plac przed Pałacem Kultury z pomnikiem z czasów PRL.', 'The main square in front of the Palace of Culture with a communist-era monument.'),
    description: L('Plac powstał w miejscu dawnej zabudowy kolejowej i stał się sceną państwowych uroczystości PRL. Stoi tu pomnik, który do dziś wywołuje dyskusje o pamięci tamtej epoki.\n\nKoncepcja nowego centrum zakłada zazielenienie placu i połączenie go z Fabryką Pełną Życia.', 'The square was laid out on former railway land and became the stage for state ceremonies in communist Poland. Its monument still sparks debate about how that era should be remembered.\n\nThe new centre plan foresees greening the square and linking it to the Factory.'),
    accessible: true, accessNote: L('Równa nawierzchnia.', 'Level paving.'), protection: null, tags: ['plac', 'prl', 'pamiec'], ill: 'city-panorama' },
  { id: 'ognisko', name: L('Dawne „Ognisko” (Paryska 4)', 'The former “Ognisko” (Paryska 4)'), kind: 'history', scope: 'city', lat: 50.3230, lng: 19.1960, site: null, building: null, districtId: 'srodmiescie',
    short: L('Nieistniejący gmach: koszary, potem dom kultury huty; dziś w jego miejscu blok mieszkalny.', 'A lost building: barracks, then the steelworks’ cultural centre; a block of flats stands there now.'),
    description: L('Budynek służył najpierw jako koszary, a później jako dom kultury huty im. Dzierżyńskiego (dziś Huta Bankowa). Rozebrano go, a w jego miejscu stanął blok przy ul. Paryskiej 4.\n\n**Obiekt nie istnieje** – to przykład, jak szybko znikają miejsca ważne dla wspólnej pamięci.', 'The building first served as barracks and later as the cultural centre of the Dzierżyński steelworks (now Huta Bankowa). It was demolished and replaced by a block of flats at ul. Paryska 4.\n\n**The building no longer exists** – it shows how quickly places that matter to shared memory can vanish.'),
    accessible: true, accessNote: L('Punkt przy chodniku.', 'Point by the pavement.'), protection: null, tags: ['nieistniejace', 'huta', 'kultura'], ill: 'map-old' },
  { id: 'palacyk-dezona', name: L('Pałacyk Dezona i „Małpi Gaj”', 'Dezon’s villa and the “Monkey Grove”'), kind: 'history', scope: 'city', lat: 50.3215, lng: 19.1980, site: null, building: null, districtId: 'srodmiescie',
    short: L('Willa dyrektora spółki francusko-włoskiej (przed 1883 r.); po wojnie siedziba milicji.', 'The villa of a Franco-Italian company director (before 1883); later a police station.'),
    description: L('Pałacyk wybudowano dla żony dyrektora spółki francusko-włoskiej – widnieje już na mapach z 1883 r. W czasie wojny zajmowało go gestapo, później milicja i policja. Z przypałacowego parku, zwanego „Małpim Gajem”, zachował się tylko fragment.\n\nTo ślad zagranicznego kapitału, który budował Zagłębie.', 'The villa was built for the wife of the director of a Franco-Italian company – it appears on maps as early as 1883. During the war it was used by the Gestapo, later by the militia and police. Only part of its park, known as the “Monkey Grove”, survives.\n\nIt is a trace of the foreign capital that built the Basin.'),
    accessible: true, accessNote: L('Oglądanie z ulicy.', 'View from the street.'), protection: null, tags: ['willa', 'kapital-zagraniczny', 'park'], ill: 'palace' },
  { id: 'kosciol-sw-barbary', name: L('Kościół św. Barbary', 'St Barbara’s Church'), kind: 'history', scope: 'city', lat: 50.3200, lng: 19.1965, site: null, building: null, districtId: 'srodmiescie',
    short: L('Kościół pod wezwaniem patronki górników, obok wejścia do Kopalni Ćwiczebnej.', 'A church dedicated to the patron saint of miners, next to the Training Mine.'),
    description: L('Przy ul. Górniczej, tuż obok kopalni ćwiczebnej, stoi kościół pod wezwaniem św. Barbary – patronki górników. Co roku 4 grudnia, w Barbórkę, górnicze tradycje ożywają tu ze szczególną siłą.\n\nTo przystanek o kulturze i obyczajach górniczych.', 'On ul. Górnicza, right next to the training mine, stands a church dedicated to St Barbara, patron of miners. Every year on 4 December – Barbórka, the miners’ day – mining traditions come alive here.\n\nThis stop is about miners’ culture and customs.'),
    accessible: true, accessNote: L('Wejście z poziomu chodnika.', 'Level entrance.'), protection: null, tags: ['kosciol', 'gornictwo', 'barborka'], ill: 'church' },
  { id: 'kosciol-golonog', name: L('Zabytkowy kościół na Wzgórzu Gołonoskim', 'Historic church on Gołonóg Hill'), kind: 'history', scope: 'city', lat: 50.3462, lng: 19.2405, site: null, building: null, districtId: 'golonog',
    short: L('Kościół i stary cmentarz na wzgórzu – najstarszy ośrodek Gołonogu.', 'A church and old cemetery on the hill – the oldest core of Gołonóg.'),
    description: L('Gołonóg wspominany jest w źródłach od XV w., a wzgórze z kościołem było jego centrum. Do 1960 r. była to osobna miejscowość.\n\nZe wzgórza dobrze widać, jak dawna wieś stała się częścią wielkiego miasta przemysłowego.', 'Gołonóg is recorded from the 15th century, and the church hill was its centre. Until 1960 it was a separate locality.\n\nFrom the hill you can see how the old village became part of a large industrial city.'),
    accessible: false, accessNote: L('Strome podejście; dojazd samochodem.', 'Steep climb; car access.'), protection: L('W granicach zespołu przyrodniczo-krajobrazowego', 'Within a nature and landscape complex'), tags: ['kosciol', 'golonog', 'sredniowiecze'], ill: 'church' },
  { id: 'miejsce-pamieci-tucznawa', name: L('Miejsce pamięci harcerzy w Tucznawie', 'Scouts’ memorial in Tucznawa'), kind: 'history', scope: 'city', lat: 50.3870, lng: 19.2700, site: null, building: null, districtId: 'tucznawa',
    short: L('Upamiętnienie 14 harcerzy zamordowanych przez Wehrmacht we wrześniu 1939 r.', 'A memorial to 14 scouts murdered by the Wehrmacht in September 1939.'),
    description: L('We wrześniu 1939 r. żołnierze Wehrmachtu zamordowali w Tucznawie czternastu harcerzy. Pamięć o nich jest ważną częścią lokalnej tożsamości.\n\nPunkt na trasie historycznej poświęcony okresowi okupacji. Prosimy o zachowanie powagi miejsca.', 'In September 1939 Wehrmacht soldiers murdered fourteen scouts in Tucznawa. Their memory is an important part of local identity.\n\nA history-trail point devoted to the occupation. Please respect the solemnity of the place.'),
    accessible: true, accessNote: L('Dojście chodnikiem.', 'Pavement access.'), protection: null, tags: ['pamiec', 'ii-wojna', 'harcerze'], ill: 'forest' },
  { id: 'dom-kultury-zabkowice', name: L('Dom Kultury Ząbkowice', 'Ząbkowice House of Culture'), kind: 'culture', scope: 'city', lat: 50.3675, lng: 19.2690, site: null, building: null, districtId: 'zabkowice',
    short: L('Dzielnicowy ośrodek kultury – zajęcia, koncerty i pamięć o ząbkowickim szkle.', 'A district cultural centre – classes, concerts and memories of Ząbkowice glass.'),
    description: L('Dom kultury w Ząbkowicach prowadzi zajęcia dla dzieci, dorosłych i seniorów oraz organizuje koncerty i wystawy. Lokalni pasjonaci gromadzą tu wspomnienia o hucie szkła i kolei.\n\nTo dobry przystanek w drodze między dworcem a dawną hutą.', 'The Ząbkowice cultural centre runs classes for children, adults and seniors and organises concerts and exhibitions. Local enthusiasts collect memories of the glassworks and railway here.\n\nA handy stop between the station and the old glassworks.'),
    accessible: true, accessNote: L('Wejście z pochylnią (dane przykładowe).', 'Ramped entrance (sample data).'), protection: null, tags: ['kultura', 'zabkowice'], ill: 'stage' },
];

